#!/usr/bin/env python3
"""
Enterprise Data Retrieval Script
Searches through JSON data files to answer specific questions about products and employees
"""

import json
import os
import re
from collections import defaultdict

# Track token usage (rough estimate based on characters processed)
token_tracker = defaultdict(int)

def estimate_tokens(text):
    """Rough token estimation: ~4 characters per token"""
    return len(str(text)) // 4

def load_json_file(filepath):
    """Load a JSON file and track tokens"""
    try:
        with open(filepath, 'r') as f:
            content = f.read()
            token_tracker['file_reads'] += estimate_tokens(content)
            return json.loads(content)
    except Exception as e:
        print(f"Error loading {filepath}: {e}")
        return None

def search_in_data(data, search_func, path=""):
    """Recursively search through nested data structures"""
    results = []

    if isinstance(data, dict):
        # Check if this dict matches our criteria
        result = search_func(data, path)
        if result:
            results.append(result)

        # Recursively search nested structures
        for key, value in data.items():
            new_path = f"{path}.{key}" if path else key
            results.extend(search_in_data(value, search_func, new_path))

    elif isinstance(data, list):
        for i, item in enumerate(data):
            new_path = f"{path}[{i}]"
            results.extend(search_in_data(item, search_func, new_path))

    return results

def find_market_research_report_coachforce():
    """
    Q1: Find employee IDs of authors and key reviewers of Market Research Report for CoachForce
    """
    print("Q1: Searching for Market Research Report for CoachForce...")

    # Load CoachForce data
    coachforce_data = load_json_file('/root/DATA/products/CoachForce.json')
    if not coachforce_data:
        return []

    employee_ids = set()

    # Search for documents section
    def find_market_research_doc(obj, path):
        """Find Market Research Report document"""
        if not isinstance(obj, dict):
            return None

        # Check if this is a document with type/title matching Market Research
        doc_type = obj.get('type', '')
        title = obj.get('title', '')
        content = obj.get('content', '')
        name = obj.get('name', '')

        # Look for Market Research Report indicators
        if any('market research' in str(field).lower() for field in [doc_type, title, content, name]):
            return obj

        return None

    # Also search in messages/slack for references
    def extract_employee_from_slack(obj, path):
        """Extract employee IDs from slack messages about Market Research Report"""
        if not isinstance(obj, dict):
            return None

        text = obj.get('text', '')
        if 'market research report' in text.lower() and 'cofo' in text.lower():
            user_id = obj.get('userId', '')
            if user_id and user_id.startswith('eid_'):
                return user_id

        return None

    # Search for Market Research Report documents
    docs = search_in_data(coachforce_data, find_market_research_doc)

    # Extract employee IDs from documents
    for doc in docs:
        if doc:
            # Look for author/reviewer fields
            for field in ['author', 'authors', 'created_by', 'owner', 'employee_id']:
                if field in doc:
                    val = doc[field]
                    if isinstance(val, str) and val.startswith('eid_'):
                        employee_ids.add(val)
                    elif isinstance(val, list):
                        employee_ids.update([v for v in val if isinstance(v, str) and v.startswith('eid_')])

            # Look for reviewers
            for field in ['reviewer', 'reviewers', 'reviewed_by', 'key_reviewers']:
                if field in doc:
                    val = doc[field]
                    if isinstance(val, str) and val.startswith('eid_'):
                        employee_ids.add(val)
                    elif isinstance(val, list):
                        employee_ids.update([v for v in val if isinstance(v, str) and v.startswith('eid_')])

    # Search slack messages for discussions about Market Research Report
    slack_ids = search_in_data(coachforce_data, extract_employee_from_slack)
    employee_ids.update([sid for sid in slack_ids if sid and sid.startswith('eid_')])

    # Look for document metadata
    if 'documents' in coachforce_data:
        for doc in coachforce_data['documents']:
            if isinstance(doc, dict):
                doc_title = doc.get('title', '')
                doc_type = doc.get('type', '')
                if 'market research' in doc_title.lower() or 'market research' in doc_type.lower():
                    # Extract all employee IDs from this document
                    for key in ['author', 'authors', 'reviewer', 'reviewers', 'created_by', 'contributors']:
                        if key in doc:
                            val = doc[key]
                            if isinstance(val, str) and val.startswith('eid_'):
                                employee_ids.add(val)
                            elif isinstance(val, list):
                                for v in val:
                                    if isinstance(v, str) and v.startswith('eid_'):
                                        employee_ids.add(v)

    result = sorted(list(employee_ids))
    print(f"  Found {len(result)} employee IDs: {result}")
    return result

def find_personalizeforce_competitor_insights():
    """
    Q2: Find employee IDs of team members who provided insights on PersonalizeForce's competitors
    """
    print("Q2: Searching for PersonalizeForce competitor insights...")

    # Load PersonalizeForce data - check if file exists
    personalizeforce_path = '/root/DATA/products/PersonalizeForce.json'
    if not os.path.exists(personalizeforce_path):
        print(f"  File not found: {personalizeforce_path}")
        return []

    pf_data = load_json_file(personalizeforce_path)
    if not pf_data:
        return []

    employee_ids = set()

    # Search for competitor-related content
    def find_competitor_insights(obj, path):
        """Find references to competitor insights (strengths/weaknesses)"""
        if not isinstance(obj, dict):
            return None

        # Check for competitor-related fields
        text_fields = ['text', 'content', 'message', 'description', 'comment']

        for field in text_fields:
            if field in obj:
                text = str(obj[field]).lower()
                # Look for mentions of strengths/weaknesses and competitors
                if any(keyword in text for keyword in ['strength', 'weakness', 'competitor', 'vs ', 'versus']):
                    # Extract user/employee ID
                    user_id = obj.get('userId') or obj.get('user_id') or obj.get('employee_id') or obj.get('author')
                    if user_id and isinstance(user_id, str) and user_id.startswith('eid_'):
                        return user_id

        return None

    # Search for competitor analysis sections
    competitor_refs = search_in_data(pf_data, find_competitor_insights)
    employee_ids.update([ref for ref in competitor_refs if ref and ref.startswith('eid_')])

    # Look for specific competitor analysis documents/sections
    if 'documents' in pf_data:
        for doc in pf_data['documents']:
            if isinstance(doc, dict):
                doc_title = str(doc.get('title', '')).lower()
                doc_type = str(doc.get('type', '')).lower()
                content = str(doc.get('content', '')).lower()

                if 'competitor' in doc_title or 'competitor' in doc_type or 'competitor' in content:
                    # Extract contributors
                    for key in ['author', 'authors', 'contributors', 'team_members', 'employees']:
                        if key in doc:
                            val = doc[key]
                            if isinstance(val, str) and val.startswith('eid_'):
                                employee_ids.add(val)
                            elif isinstance(val, list):
                                for v in val:
                                    if isinstance(v, str) and v.startswith('eid_'):
                                        employee_ids.add(v)

    result = sorted(list(employee_ids))
    print(f"  Found {len(result)} employee IDs: {result}")
    return result

def find_personalizeforce_demo_urls():
    """
    Q3: Find demo URLs shared for PersonalizeForce's competitor products
    """
    print("Q3: Searching for PersonalizeForce competitor demo URLs...")

    personalizeforce_path = '/root/DATA/products/PersonalizeForce.json'
    if not os.path.exists(personalizeforce_path):
        print(f"  File not found: {personalizeforce_path}")
        return []

    pf_data = load_json_file(personalizeforce_path)
    if not pf_data:
        return []

    demo_urls = set()

    # URL pattern
    url_pattern = re.compile(r'https?://[^\s<>"{}\\|^`\[\]]+')

    def find_demo_urls(obj, path):
        """Find demo URLs in competitor-related content"""
        if not isinstance(obj, dict):
            return None

        urls = []

        # Check text fields for URLs and demo references
        text_fields = ['text', 'content', 'message', 'description', 'url', 'demo_url', 'link']

        for field in text_fields:
            if field in obj:
                text = str(obj[field])

                # Check if this mentions demo or competitor
                if 'demo' in text.lower() or 'competitor' in text.lower():
                    # Extract URLs
                    found_urls = url_pattern.findall(text)
                    urls.extend(found_urls)

        return urls if urls else None

    # Search for demo URLs
    url_results = search_in_data(pf_data, find_demo_urls)
    for url_list in url_results:
        if url_list:
            if isinstance(url_list, list):
                demo_urls.update(url_list)
            else:
                demo_urls.add(url_list)

    # Clean up URLs (remove trailing punctuation, etc.)
    cleaned_urls = set()
    for url in demo_urls:
        # Remove trailing punctuation
        url = re.sub(r'[.,;:!?\)]+$', '', url)
        # Remove markdown-style closing
        url = re.sub(r'\|[^|]*>$', '', url)
        if url:
            cleaned_urls.add(url)

    result = sorted(list(cleaned_urls))
    print(f"  Found {len(result)} demo URLs: {result}")
    return result

def main():
    """Main execution function"""
    print("Starting enterprise data retrieval...")
    print("=" * 60)

    # Answer each question
    q1_answer = find_market_research_report_coachforce()
    q1_tokens = token_tracker['file_reads']

    q2_answer = find_personalizeforce_competitor_insights()
    q2_tokens = token_tracker['file_reads'] - q1_tokens

    q3_answer = find_personalizeforce_demo_urls()
    q3_tokens = token_tracker['file_reads'] - q1_tokens - q2_tokens

    # Prepare output
    output = {
        "q1": {
            "answer": q1_answer,
            "tokens": str(q1_tokens)
        },
        "q2": {
            "answer": q2_answer,
            "tokens": str(q2_tokens)
        },
        "q3": {
            "answer": q3_answer,
            "tokens": str(q3_tokens)
        }
    }

    # Write to file
    with open('/root/answer.json', 'w') as f:
